function reverseDegree(s) {
  const zCode = 'z'.charCodeAt(0);
  let total = 0;
  for (let i = 0; i < s.length; i++) {
    const weight = zCode - s.charCodeAt(i) + 1;
    const position = i + 1;
    total += weight * position;
  }
  return total;
}

