function reverseDegree(s) {
  const reversedAlphabet = 'zyxwvutsrqponmlkjihgfedcba';
  let sum = 0;
  [...s].forEach((letter, index) => {
    sum += (reversedAlphabet.indexOf(letter) + 1) * (index + 1);
  });
  return sum;
}

