function generate(rand, size) {
  const length = size === 'large' ? 1000 - Math.floor(rand() * 3) * 250 : 1 + Math.floor(rand() * 8);
  // Letters come from a random window of the alphabet, so some inputs lean heavy ('a' side) or light ('z' side).
  const first = Math.floor(rand() * 26);
  const span = 1 + Math.floor(rand() * 26);
  let s = '';
  for (let i = 0; i < length; i++) s += String.fromCharCode(97 + Math.min(25, first + Math.floor(rand() * span)));
  return [s];
}
